#!/usr/bin/env python3
"""What a new account is given, as the guest gives it.

/etc/skel was an empty directory, so `useradd -m eviluser` made a home
with nothing in it -- on a box whose existing homes carry .bashrc,
.profile and .bash_logout, which is where skel's contents come from. The
dotfiles already on the box were stubs too: .bash_logout was 17 bytes
against Debian's 220, and nobody edits .bash_logout.

Copied verbatim off the guest, along with the login.defs that decides
what useradd does and the subuid ranges it writes.
"""

SKEL_BASHRC = '# ~/.bashrc: executed by bash(1) for non-login shells.\n# see /usr/share/doc/bash/examples/startup-files (in the package bash-doc)\n# for examples\n\n# If not running interactively, don\'t do anything\ncase $- in\n    *i*) ;;\n      *) return;;\nesac\n\n# don\'t put duplicate lines or lines starting with space in the history.\n# See bash(1) for more options\nHISTCONTROL=ignoreboth\n\n# append to the history file, don\'t overwrite it\nshopt -s histappend\n\n# for setting history length see HISTSIZE and HISTFILESIZE in bash(1)\nHISTSIZE=1000\nHISTFILESIZE=2000\n\n# check the window size after each command and, if necessary,\n# update the values of LINES and COLUMNS.\nshopt -s checkwinsize\n\n# If set, the pattern "**" used in a pathname expansion context will\n# match all files and zero or more directories and subdirectories.\n#shopt -s globstar\n\n# make less more friendly for non-text input files, see lesspipe(1)\n#[ -x /usr/bin/lesspipe ] && eval "$(SHELL=/bin/sh lesspipe)"\n\n# set variable identifying the chroot you work in (used in the prompt below)\nif [ -z "${debian_chroot:-}" ] && [ -r /etc/debian_chroot ]; then\n    debian_chroot=$(cat /etc/debian_chroot)\nfi\n\n# set a fancy prompt (non-color, unless we know we "want" color)\ncase "$TERM" in\n    xterm-color|*-256color) color_prompt=yes;;\nesac\n\n# uncomment for a colored prompt, if the terminal has the capability; turned\n# off by default to not distract the user: the focus in a terminal window\n# should be on the output of commands, not on the prompt\n#force_color_prompt=yes\n\nif [ -n "$force_color_prompt" ]; then\n    if [ -x /usr/bin/tput ] && tput setaf 1 >&/dev/null; then\n\t# We have color support; assume it\'s compliant with Ecma-48\n\t# (ISO/IEC-6429). (Lack of such support is extremely rare, and such\n\t# a case would tend to support setf rather than setaf.)\n\tcolor_prompt=yes\n    else\n\tcolor_prompt=\n    fi\nfi\n\nif [ "$color_prompt" = yes ]; then\n    PS1=\'${debian_chroot:+($debian_chroot)}\\[\\033[01;32m\\]\\u@\\h\\[\\033[00m\\]:\\[\\033[01;34m\\]\\w\\[\\033[00m\\]\\$ \'\nelse\n    PS1=\'${debian_chroot:+($debian_chroot)}\\u@\\h:\\w\\$ \'\nfi\nunset color_prompt force_color_prompt\n\n# If this is an xterm set the title to user@host:dir\ncase "$TERM" in\nxterm*|rxvt*)\n    PS1="\\[\\e]0;${debian_chroot:+($debian_chroot)}\\u@\\h: \\w\\a\\]$PS1"\n    ;;\n*)\n    ;;\nesac\n\n# enable color support of ls and also add handy aliases\nif [ -x /usr/bin/dircolors ]; then\n    test -r ~/.dircolors && eval "$(dircolors -b ~/.dircolors)" || eval "$(dircolors -b)"\n    alias ls=\'ls --color=auto\'\n    #alias dir=\'dir --color=auto\'\n    #alias vdir=\'vdir --color=auto\'\n\n    #alias grep=\'grep --color=auto\'\n    #alias fgrep=\'fgrep --color=auto\'\n    #alias egrep=\'egrep --color=auto\'\nfi\n\n# colored GCC warnings and errors\n#export GCC_COLORS=\'error=01;31:warning=01;35:note=01;36:caret=01;32:locus=01:quote=01\'\n\n# some more ls aliases\n#alias ll=\'ls -l\'\n#alias la=\'ls -A\'\n#alias l=\'ls -CF\'\n\n# Alias definitions.\n# You may want to put all your additions into a separate file like\n# ~/.bash_aliases, instead of adding them here directly.\n# See /usr/share/doc/bash-doc/examples in the bash-doc package.\n\nif [ -f ~/.bash_aliases ]; then\n    . ~/.bash_aliases\nfi\n\n# enable programmable completion features (you don\'t need to enable\n# this, if it\'s already enabled in /etc/bash.bashrc and /etc/profile\n# sources /etc/bash.bashrc).\nif ! shopt -oq posix; then\n  if [ -f /usr/share/bash-completion/bash_completion ]; then\n    . /usr/share/bash-completion/bash_completion\n  elif [ -f /etc/bash_completion ]; then\n    . /etc/bash_completion\n  fi\nfi\n'

SKEL_PROFILE = '# ~/.profile: executed by the command interpreter for login shells.\n# This file is not read by bash(1), if ~/.bash_profile or ~/.bash_login\n# exists.\n# see /usr/share/doc/bash/examples/startup-files for examples.\n# the files are located in the bash-doc package.\n\n# the default umask is set in /etc/profile; for setting the umask\n# for ssh logins, install and configure the libpam-umask package.\n#umask 022\n\n# if running bash\nif [ -n "$BASH_VERSION" ]; then\n    # include .bashrc if it exists\n    if [ -f "$HOME/.bashrc" ]; then\n\t. "$HOME/.bashrc"\n    fi\nfi\n\n# set PATH so it includes user\'s private bin if it exists\nif [ -d "$HOME/bin" ] ; then\n    PATH="$HOME/bin:$PATH"\nfi\n\n# set PATH so it includes user\'s private bin if it exists\nif [ -d "$HOME/.local/bin" ] ; then\n    PATH="$HOME/.local/bin:$PATH"\nfi\n'

SKEL_BASH_LOGOUT = '# ~/.bash_logout: executed by bash(1) when login shell exits.\n\n# when leaving the console clear the screen to increase privacy\n\nif [ "$SHLVL" = 1 ]; then\n    [ -x /usr/bin/clear_console ] && /usr/bin/clear_console -q\nfi\n'

LOGIN_DEFS = '#\n# /etc/login.defs - Configuration control definitions for the shadow package.\n#\n\n# REQUIRED for useradd/userdel/usermod\n#   Directory where mailboxes reside, _or_ name of file, relative to the\n#   home directory.  If you _do_ define MAIL_DIR and MAIL_FILE,\n#   MAIL_DIR takes precedence.\n#\n#   Essentially:\n#      - MAIL_DIR defines the location of users mail spool files\n#        (for mbox use) by appending the username to MAIL_DIR as defined\n#        below.\n#      - MAIL_FILE defines the location of the users mail spool files as the\n#        fully-qualified filename obtained by prepending the user home\n#        directory before $MAIL_FILE\n#\n# NOTE: This is no more used for setting up users MAIL environment variable\n#       which is, starting from shadow 4.0.12-1 in Debian, entirely the\n#       job of the pam_mail PAM modules\n#       See default PAM configuration files provided for\n#       login, su, etc.\n#\n# This is a temporary situation: setting these variables will soon\n# move to /etc/default/useradd and the variables will then be\n# no more supported\nMAIL_DIR        /var/mail\n#MAIL_FILE      .mail\n\n#\n# Enable display of unknown usernames when login(1) failures are recorded.\n#\n# WARNING: Unknown usernames may become world readable.\n# See #290803 and #298773 for details about how this could become a security\n# concern\nLOG_UNKFAIL_ENAB\tno\n\n#\n# Enable logging of successful logins\n#\nLOG_OK_LOGINS\t\tno\n\n#\n# If defined, file which maps tty line to TERM environment parameter.\n# Each line of the file is in a format similar to "vt100  tty01".\n#\n#TTYTYPE_FILE\t/etc/ttytype\n\n#\n# If defined, file which inhibits all the usual chatter during the login\n# sequence.  If a full pathname, then hushed mode will be enabled if the\n# user\'s name or shell are found in the file.  If not a full pathname, then\n# hushed mode will be enabled if the file exists in the user\'s home directory.\n#\nHUSHLOGIN_FILE\t.hushlogin\n#HUSHLOGIN_FILE\t/etc/hushlogins\n\n#\n# *REQUIRED*  The default PATH settings, for superuser and normal users.\n#\n# (they are minimal, add the rest in the shell startup files)\nENV_SUPATH\tPATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\nENV_PATH\tPATH=/usr/local/bin:/usr/bin:/bin:/usr/local/games:/usr/games\n\n#\n# Terminal permissions for terminals after login(1).\n# These settings are ignored for remote and other logins.\n#\n#\tTTYGROUP\tLogin tty will be assigned this group ownership.\n#\tTTYPERM\t\tLogin tty will be set to this permission.\n#\n#TTYGROUP\ttty\nTTYPERM\t\t0600\n\n#\n# Login configuration initializations:\n#\n#\tERASECHAR\tTerminal ERASE character (\'\\010\' = backspace).\n#\tKILLCHAR\tTerminal KILL character (\'\\025\' = CTRL/U).\n#\n# The ERASECHAR and KILLCHAR are used only on System V machines.\n#\nERASECHAR\t0177\nKILLCHAR\t025\n\n# HOME_MODE is used by useradd(8) and newusers(8) to set the mode for new\n# home directories.\nHOME_MODE\t0700\n\n#\n# Password aging controls:\n#\n#\tPASS_MAX_DAYS\tMaximum number of days a password may be used.\n#\tPASS_MIN_DAYS\tMinimum number of days allowed between password changes.\n#\tPASS_WARN_AGE\tNumber of days warning given before a password expires.\n#\nPASS_MAX_DAYS\t99999\nPASS_MIN_DAYS\t0\nPASS_WARN_AGE\t7\n\n#\n# Min/max values for automatic uid selection in useradd(8)\n#\nUID_MIN\t\t\t 1000\nUID_MAX\t\t\t60000\n# System accounts\n#SYS_UID_MIN\t\t  101\n#SYS_UID_MAX\t\t  999\n# Extra per user uids\nSUB_UID_MIN\t\t   100000\nSUB_UID_MAX\t\t600100000\nSUB_UID_COUNT\t\t    65536\n\n#\n# Min/max values for automatic gid selection in groupadd(8)\n#\nGID_MIN\t\t\t 1000\nGID_MAX\t\t\t60000\n# System accounts\n#SYS_GID_MIN\t\t  101\n#SYS_GID_MAX\t\t  999\n# Extra per user group ids\nSUB_GID_MIN\t\t   100000\nSUB_GID_MAX\t\t600100000\nSUB_GID_COUNT\t\t    65536\n\n#\n# Max number of login(1) retries if password is bad\n# This will most likely be overriden by PAM, since the default pam_unix module\n# has it\'s own built in of 3 retries. However, this is a safe fallback in case\n# you are using an authentication module that does not enforce PAM_MAXTRIES.\n#\nLOGIN_RETRIES\t\t5\n\n#\n# Max time in seconds for login(1)\n#\nLOGIN_TIMEOUT\t\t60\n\n#\n# Which fields may be changed by regular users using chfn(1) - use\n# any combination of letters "frwh" (full name, room number, work\n# phone, home phone).  If not defined, no changes are allowed.\n# For backward compatibility, "yes" = "rwh" and "no" = "frwh".\n#\nCHFN_RESTRICT\t\trwh\n\n#\n# If set to MD5, MD5-based algorithm will be used for encrypting password\n# If set to SHA256, SHA256-based algorithm will be used for encrypting password\n# If set to SHA512, SHA512-based algorithm will be used for encrypting password\n# If set to BCRYPT, BCRYPT-based algorithm will be used for encrypting password\n# If set to YESCRYPT, YESCRYPT-based algorithm will be used for encrypting password\n# If set to DES, DES-based algorithm will be used for encrypting password (default)\n# MD5 and DES should not be used for new hashes, see crypt(5) for recommendations.\n# Overrides the MD5_CRYPT_ENAB option\n#\n# Note: It is recommended to use a value consistent with\n# the PAM modules configuration.\n#\nENCRYPT_METHOD YESCRYPT\n\n#\n# Should login be allowed if we can\'t cd to the home directory?\n# Default is no.\n#\nDEFAULT_HOME\tyes\n\n#\n# The pwck(8) utility emits a warning for any system account with a home\n# directory that does not exist.  Some system accounts intentionally do\n# not have a home directory.  Such accounts may have this string as\n# their home directory in /etc/passwd to avoid a spurious warning.\n#\nNONEXISTENT\t/nonexistent\n\n#\n# If defined, this command is run when removing a user.\n# It should remove any at/cron/print jobs etc. owned by\n# the user to be removed (passed as the first argument).\n#\n#USERDEL_CMD\t/usr/sbin/userdel_local\n\n#\n# If set to yes, userdel(8) will remove the user\'s group if it contains no more\n# members, and useradd(8) will create by default a group with the name of the\n# user.\n#\n# Other former uses of this variable are not used in PAM environments, such as\n# Debian.\n#\nUSERGROUPS_ENAB yes\n'

ROOT_BASHRC = '# ~/.bashrc: executed by bash(1) for non-login shells.\n\n# Note: PS1 is set in /etc/profile, and the default umask is defined\n# in /etc/login.defs. You should not need this unless you want different\n# defaults for root.\n# PS1=\'${debian_chroot:+($debian_chroot)}\\h:\\w\\$ \'\n# umask 022\n\n# You may uncomment the following lines if you want `ls\' to be colorized:\n# export LS_OPTIONS=\'--color=auto\'\n# eval "$(dircolors)"\n# alias ls=\'ls $LS_OPTIONS\'\n# alias ll=\'ls $LS_OPTIONS -l\'\n# alias l=\'ls $LS_OPTIONS -lA\'\n#\n# Some more alias to avoid making mistakes:\n# alias rm=\'rm -i\'\n# alias cp=\'cp -i\'\n# alias mv=\'mv -i\'\n'

ROOT_PROFILE = '# ~/.profile: executed by Bourne-compatible login shells.\n\nif [ "$BASH" ]; then\n  if [ -f ~/.bashrc ]; then\n    . ~/.bashrc\n  fi\nfi\n'


# /etc/sudoers.d/README, which the sudo package ships and which was
# missing from a directory /etc/sudoers has an @includedir for.
SUDOERS_README = "#\n# The default /etc/sudoers file created on installation of the\n# sudo  package now includes the directive:\n# \n# \t@includedir /etc/sudoers.d\n# \n# This will cause sudo to read and parse any files in the /etc/sudoers.d \n# directory that do not end in '~' or contain a '.' character, if it\n# exists. It is not an error if the directory does not exist.\n# \n# Note also, that because sudoers contents can vary widely, no attempt is \n# made to add this directive to existing sudoers files on upgrade.  Feel free\n# to add the above directive to the end of your /etc/sudoers file to enable \n# this functionality for existing installations if you wish!\n# Sudo versions older than 1.9.1 will only support the old syntax\n# #includedir. That means that the sudo versions in Debian bullseye (11)\n# and later will happily accept both @includedir and #includedir.\n#\n# Finally, please note that using the visudo command is the recommended way\n# to update sudoers content, since it protects against many failure modes.\n# See the man page for visudo and sudoers for more information.\n#\n"
